#!/usr/bin/env node
/**
 * The published numbers are checked against a stored file. Nothing checked the file.
 *
 * `verify:docs` compares every figure in the readme to `eval/results/*.json` — the
 * held-out precision, the H1–H3 verdicts, the grid size, the lift. That closes the gap
 * between the prose and the harness output, and leaves open the one behind it: the
 * harness output is a *committed artifact*, regenerated by hand. Change a detector and
 * every gate stays green while `breach.json` describes the detector you used to have.
 *
 * That is not hypothetical here. The breach engine gained a seventh detector, the
 * projection that counts a derived verdict was fixed in three places, and the money a
 * derived breach is worth changed. Re-running the harnesses by hand afterwards found all
 * five deterministic reports byte-identical — which is the right answer, and was worth
 * nothing as a guarantee, because the next change gets no such check.
 *
 * So: re-run them and insist the numbers come back the same.
 *
 * **This gate does not write to the repository.** The harnesses take `OWED_EVAL_RESULTS`
 * and are pointed at a temp directory, so `eval/results/` is only ever read. The first
 * version of this file did the opposite — it let each harness overwrite the tracked report
 * and restored the original in a `finally` — and that was wrong in a way that only shows
 * up when something goes wrong: a `finally` does not run on SIGINT, this gate sits in the
 * middle of `pnpm verify`, which is exactly the command people cancel, and Ctrl-C signals
 * the whole process group, so a harness could die *inside* `writeFileSync` and leave a
 * tracked report truncated with nothing left to restore it. CI cancels superseded pushes
 * by default, so that was the normal path, not an exotic one.
 *
 * Not writing is the fix. It needs no signal handler, because there is nothing to undo.
 * `scripts/draw-architecture.mjs --check` already makes the same argument here, and
 * `verify-docs.mjs` consumes it with the reason attached: a gate that regenerates the file
 * it is checking cannot fail.
 *
 * `latency.json` is excluded by name. It is the one report that is a property of the
 * machine rather than of the code — it carries the core count and load average it was
 * taken under — and re-running it would fail on a quiet laptop as readily as on a busy
 * one. The readme quotes no latency figure for the same reason.
 */
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const RESULTS = join(REPO_ROOT, "eval", "results");

/** The five reports that are a pure function of the code and a fixed seed. */
const DETERMINISTIC = ["extraction", "breach", "recourse", "learning", "robustness"];

/** A harness that prints tables and runs a 270-cell grid; neither bound is near normal. */
const MAX_OUTPUT_BYTES = 32 * 1024 * 1024;
const HARNESS_TIMEOUT_MS = 10 * 60_000;

/** The same shape as every sibling gate, so a failure and its count cannot disagree. */
const failures = [];
function want(label, ok, detail) {
  process.stdout.write(`  ${ok ? "ok " : "FAIL"} ${label} — ${detail}\n`);
  if (!ok) failures.push(`${label}: ${detail}`);
}

/**
 * Parse without throwing, because a report is a file on disk and files get truncated.
 *
 * The first version called `JSON.parse` bare: an unparseable regenerated report aborted
 * the loop with a raw stack, the remaining harnesses never ran, and nothing was reported.
 * `draw-architecture.mjs` and `verify-graph.mjs` both already read committed artifacts
 * this way.
 */
function parsed(text) {
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (cause) {
    return { ok: false, why: cause instanceof Error ? cause.message : String(cause) };
  }
}

function read(path) {
  try {
    return { ok: true, text: readFileSync(path, "utf8") };
  } catch (cause) {
    return { ok: false, why: cause instanceof Error ? cause.message : String(cause) };
  }
}

/** `JSON.stringify(-0)` is `"0"`, which would render a real difference as `0 became 0`. */
function show(value) {
  return Object.is(value, -0) ? "-0" : JSON.stringify(value);
}

/**
 * Every figure that moved, not just the first.
 *
 * The first version returned on the first difference, so a detector change that moved
 * twelve numbers reported one — and the operator fixed one thing at a time to find the
 * rest. Capped, because a report with a different shape differs everywhere.
 */
function differences(before, after, path = "", found = [], cap = 8) {
  if (found.length >= cap || Object.is(before, after)) return found;

  const shape = (value) =>
    value === null ? "null" : Array.isArray(value) ? "array" : typeof value;
  const where = path === "" ? "(root)" : path.replace(/^\./, "");

  if (shape(before) !== shape(after)) {
    found.push(`${where}: ${shape(before)} became ${shape(after)}`);
    return found;
  }

  if (Array.isArray(before)) {
    if (before.length !== after.length) {
      found.push(`${where}: ${before.length} entries became ${after.length}`);
      return found;
    }
    for (let index = 0; index < before.length && found.length < cap; index += 1) {
      differences(before[index], after[index], `${path}[${index}]`, found, cap);
    }
    return found;
  }

  if (shape(before) === "object") {
    // `Object.hasOwn`, not `key in`: a report gaining a key named `toString` would
    // otherwise be compared against `Object.prototype.toString` and reported as
    // "function became string".
    for (const key of new Set([...Object.keys(before), ...Object.keys(after)])) {
      if (found.length >= cap) break;
      if (!Object.hasOwn(before, key)) found.push(`${where}.${key}: appeared`);
      else if (!Object.hasOwn(after, key)) found.push(`${where}.${key}: disappeared`);
      else differences(before[key], after[key], `${path}.${key}`, found, cap);
    }
    return found;
  }

  found.push(`${where}: ${show(before)} became ${show(after)}`);
  return found;
}

/** Read the committed reports first: a missing one is a failure before anything runs. */
const stored = new Map();
for (const name of DETERMINISTIC) {
  const path = join(RESULTS, `${name}.json`);
  const file = read(path);
  if (!file.ok) {
    want(`${name}.json is committed`, false, `${file.why} — run \`pnpm eval:all\` and commit it`);
    continue;
  }
  const json = parsed(file.text);
  if (!json.ok) {
    want(`${name}.json is valid JSON`, false, `the committed file does not parse: ${json.why}`);
    continue;
  }
  stored.set(name, json.value);
}

const out = mkdtempSync(join(tmpdir(), "owed-eval-"));
let rederived = 0;

try {
  process.stdout.write("\n--- the committed reports, re-derived ---\n");

  for (const name of DETERMINISTIC) {
    if (!stored.has(name)) continue;

    const run = spawnSync("pnpm", ["--filter", "@owed/eval", name], {
      cwd: REPO_ROOT,
      encoding: "utf8",
      // The harnesses print their own tables; this gate only wants the numbers.
      stdio: ["ignore", "pipe", "pipe"],
      env: { ...process.env, OWED_EVAL_RESULTS: out },
      maxBuffer: MAX_OUTPUT_BYTES,
      timeout: HARNESS_TIMEOUT_MS,
    });

    /**
     * `.error` as well as `.status`, which is what every other spawning gate here does.
     *
     * Without it a harness that never launched — `pnpm` off PATH, an OOM kill, a
     * `maxBuffer` overflow — reported `exited null` and threw the real reason away, five
     * times over, with no indication that nothing had run.
     */
    if (run.error !== undefined || run.status !== 0) {
      const why =
        run.error !== undefined
          ? run.error.message
          : run.signal !== null
            ? `killed by ${run.signal}`
            : `exited ${run.status}`;
      want(`${name} harness ran`, false, why);
      const tail = `${run.stdout ?? ""}${run.stderr ?? ""}`.trim().split("\n").slice(-4);
      for (const line of tail) if (line !== "") process.stdout.write(`       ${line}\n`);
      continue;
    }

    const file = read(join(out, `${name}.json`));
    if (!file.ok) {
      want(`${name}.json was re-derived`, false, `the harness wrote nothing here: ${file.why}`);
      continue;
    }
    const json = parsed(file.text);
    if (!json.ok) {
      want(`${name}.json was re-derived`, false, `the new report does not parse: ${json.why}`);
      continue;
    }

    rederived += 1;
    const moved = differences(stored.get(name), json.value);
    want(
      `${name}.json`,
      moved.length === 0,
      moved.length === 0 ? "re-derived identically" : moved.join("; "),
    );
  }
} finally {
  // Belt and braces only: nothing in the repository depends on this running. On SIGINT it
  // does not run, and the temp directory is left for the OS — which is the whole point of
  // writing there instead of into `eval/results/`.
  rmSync(out, { recursive: true, force: true });
}

process.stdout.write(
  `\n  ${rederived} of ${DETERMINISTIC.length} report(s) re-derived; latency.json excluded,` +
    " being a property of the machine\n",
);

if (failures.length > 0) {
  process.stdout.write(
    `\n${failures.length} problem(s):\n${failures.map((line) => `  ${line}`).join("\n")}\n\n` +
      "A drifted report is not a failing test. The readme's figures are checked against\n" +
      "these files by `verify:docs`, so the prose and the file agree while both describe\n" +
      "code that no longer exists. Re-run `pnpm eval:all`, read what moved, and commit it\n" +
      "with the reason — the numbers are pre-registered, so a change to one is a finding.\n",
  );
  // `process.exitCode` rather than `process.exit`, which can drop buffered writes when
  // stdout is a pipe — and `pnpm verify` is always a pipe.
  process.exitCode = 1;
} else {
  process.stdout.write("\nEvery published figure is still what the code produces.\n");
}
